"use client";

import { useEffect, useState } from "react";
import type { SearchIndex } from "@/lib/search/types";

/**
 * One fetch of `public/search-index.json`, cached for the session.
 *
 * The palette must not refetch per keystroke or per open: the index is a
 * static build artifact (regenerated by predev/prebuild), so a module-level
 * promise cache is the right lifetime — and it is why results are instant
 * and local once loaded.
 */
type IndexState =
	| { status: "idle" }
	| { status: "loading" }
	| { status: "ready"; index: SearchIndex }
	| { status: "error"; message: string };

let cached: SearchIndex | null = null;
let inflight: Promise<SearchIndex> | null = null;

function loadIndex(): Promise<SearchIndex> {
	if (cached) return Promise.resolve(cached);
	if (!inflight) {
		inflight = fetch("/search-index.json")
			.then((response) => {
				if (!response.ok) throw new Error(`HTTP ${response.status}`);
				return response.json() as Promise<SearchIndex>;
			})
			.then((index) => {
				cached = index;
				inflight = null;
				return index;
			})
			.catch((error: unknown) => {
				inflight = null;
				throw error;
			});
	}
	return inflight;
}

export function useSearchIndex(enabled: boolean) {
	const [state, setState] = useState<IndexState>(
		cached ? { status: "ready", index: cached } : { status: "idle" },
	);

	useEffect(() => {
		if (!enabled) return;
		if (state.status === "ready" || state.status === "loading") return;
		setState({ status: "loading" });
		loadIndex()
			.then((index) => setState({ status: "ready", index }))
			.catch((error: unknown) =>
				setState({
					status: "error",
					message: error instanceof Error ? error.message : "unknown error",
				}),
			);
	}, [enabled, state.status]);

	function retry() {
		cached = null;
		inflight = null;
		setState({ status: "idle" });
	}

	return { state, retry };
}
